{
  "selections": [
    {
      "trait_id": "/core_belief/young_schema",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사가 '밖에서 붙잡고 싶을 때 어떤 순간이 먼저 올 것 같냐'고 물은 것은 유기/불안정 스키마가 어떤 상황에서 활성화되는지를 내담자가 스스로 예측하도록 유도하는 질문이며, 성장 경험에서 형성된 이 스키마가 그 예측의 근거가 됨."
    },
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사의 질문은 '사랑하는 사람이 결국 떠난다'는 핵심 신념이 밖에서 어떤 장면을 통해 재확인되리라 기대하는지를 묻는 것으로, 내담자가 떠올릴 '가장 먼저 올 순간'은 이 신념이 작동하는 전형적 장면일 것임."
    },
    {
      "trait_id": "/intermediate_beliefs/rule",
      "background_ids": ["/situations/0", "/situations/3"],
      "relevance": "'조금이라도 멀어진 느낌이 들면 즉시 붙잡아야 한다'는 규칙이 상담사의 질문과 직접 연결됨. 내담자가 예측할 '가장 먼저 올 순간'은 이 규칙이 발동되는 상황—답장 지연, 각자의 시간 요구 등—일 것이며, 상황 사례 0과 3이 그 규칙의 구체적 작동 예시임."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_positive",
      "background_ids": [],
      "relevance": "'계속 확인하고 더 잘하면 떠나는 것을 막을 수 있다'는 긍정 가정이 붙잡고 싶은 충동의 동기를 설명하므로, 상담사의 질문에 대한 내담자의 예측에 이 가정이 반영될 것임."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": ["/childhood_data"],
      "relevance": "'확인을 멈추면 아버지처럼 예고 없이 사라질 것'이라는 부정 가정이 붙잡지 않을 때의 공포를 설명하며, 상담사가 '붙잡지 않아도 괜찮다'는 새 경험을 밖으로 확장하는 질문을 했을 때 내담자가 가장 먼저 느낄 저항의 근거임."
    },
    {
      "trait_id": "/coping_strategies/0",
      "background_ids": ["/situations/0"],
      "relevance": "상담사가 '붙잡고 싶을 때'의 구체적 순간을 물었으므로, 답장 지연 시 SNS 확인·연속 메시지 발송이라는 가장 빈번한 대처 전략이 내담자의 예측에서 가장 먼저 떠오를 가능성이 높음. 상황 사례 0이 그 장면을 구체화함."
    },
    {
      "trait_id": "/coping_strategies/2",
      "background_ids": ["/situations/3"],
      "relevance": "'각자의 시간'을 요구받는 상황은 상담사가 질문한 '밖에서'의 대표적인 장면이며, 상황 사례 3에서 겉으로 허락하고도 뒤에서 접속 흔적을 살피는 패턴이 나타남. 내담자가 예측할 다음 순간과 직접 연결됨."
    },
    {
      "trait_id": "/coping_strategies/3",
      "background_ids": ["/situations/1"],
      "relevance": "다툰 후 매달리는 패턴은 '이러면 오래 못 간다'는 연인의 말 이후 현재 상담의 직접적 계기가 된 대처 전략이며, 상황 사례 1에서 그 결과(상대의 지친 반응)가 나타남. 상담사가 질문한 '붙잡고 싶은 순간'이 이미 직전까지 벌어진 일임."
    },
    {
      "trait_id": "/coping_strategies/4",
      "background_ids": ["/situations/3"],
      "relevance": "'우연을 가장해 찾아감'은 불안이 가장 심할 때 나타나는 가장 극적인 붙잡기 행동으로, 상담사가 '밖에서'의 가능성을 물었을 때 내담자가 가장 통제하기 어려울 것이라 예상하는 순간일 수 있음."
    }
  ]
}

